 public static function guardPlanMutation(int $id): void {$order=wc_get_order($id);if(!$order)return;$d=self::data($order);if(!empty($d['committed_fingerprint'])||!empty($d['handover'])||isset(self::catalog()['__commits'][(string)$id]))throw new \RuntimeException('طرح بسته‌بندی این سفارش پس از مصرف موجودی یا تحویل قفل است.');}
 public static function expected($order): array {
  $units=Packing::units($order);$products=[];foreach($units as $unit){$p=wc_get_product($unit['product_id']);$codes=[];if($p){$codes[]=(string)$p->get_sku();if(method_exists($p,'get_global_unique_id'))$codes[]=(string)$p->get_global_unique_id();foreach(['_barcode','_hm_mahex_barcode'] as $key)$codes[]=(string)$p->get_meta($key,true);} $products[$unit['product_id']]=array_values(array_unique(array_filter($codes,static fn($v)=>$v!=='')));}
  foreach($units as &$unit)$unit['codes']=$products[$unit['product_id']]??[];unset($unit);return $units;
