 public static function scanUnit(array $units,array $scanned,string $code): string {
  $matches=[];foreach($units as $id=>$unit)if(in_array($code,$unit['codes']??[],true))$matches[$unit['product_id']][]=$id;
  if(count($matches)!==1)throw new \InvalidArgumentException(count($matches)?'بارکد بین چند محصول تکراری است.':'این بارکد یا SKU در سفارش وجود ندارد.');
  foreach(reset($matches) as $id)if(!isset($scanned[$id]))return (string)$id;throw new \InvalidArgumentException('تعداد این کالا کامل شده؛ اسکن اضافه مجاز نیست.');
 }
 public static function variance(float $actual,float $estimated): float {return $estimated>0?abs($actual-$estimated)/$estimated*100:0;}
 public static function mediaIds(array $ids,string $kind='image'): array {
  $out=[];if(count($ids)>12)throw new \InvalidArgumentException('حداکثر ۱۲ فایل مجاز است.');foreach($ids as $id){$id=absint($id);if(!$id||get_post_type($id)!=='attachment'||!(current_user_can('edit_post',$id)||(current_user_can('upload_files')&&(int)get_post_field('post_author',$id)===get_current_user_id())))throw new \InvalidArgumentException('فایل رسانه قابل دسترسی نیست.');$mime=get_post_mime_type($id);if(($kind==='image'&&!in_array($mime,['image/jpeg','image/png','image/webp'],true))||($kind==='pdf'&&$mime!=='application/pdf'))throw new \InvalidArgumentException('نوع فایل مجاز نیست.');$out[]=$id;}return array_values(array_unique($out));
 }
 public static function catalog(): array {$s=get_option(self::STOCK,[]);return is_array($s)?$s:[];}
 public static function stockSave(): void {
  if(!Access::can('settings'))wp_die('دسترسی مجاز نیست.','',['response'=>403]);check_admin_referer('hm_mahex_v33_stock');$raw=isset($_POST['catalog'])&&is_string($_POST['catalog'])?json_decode(wp_unslash($_POST['catalog']),true):null;
  if(!is_array($raw)||count($raw)>200)wp_die('جدول JSON معتبر با حداکثر ۲۰۰ ماده وارد کنید.');$clean=[];foreach($raw as $id=>$row){if(!is_array($row)||!preg_match('/^[a-z0-9_-]{1,80}$/',(string)$id))wp_die('شناسه ماده معتبر نیست.');$clean[$id]=['name'=>sanitize_text_field((string)($row['name']??$id))];foreach(['stock','unit_cost_irr','min_stock','target_stock'] as $field){$value=$row[$field]??0;if(!is_numeric($value)||!is_finite((float)$value)||(float)$value<0||$value>1000000000000)wp_die('مقدار موجودی یا هزینه معتبر نیست.');$clean[$id][$field]=(float)$value;}}
  $guard=new \HoseinMomeni\MahexWoo\Shipments\OptionOperationLock();if(!$guard->acquire(-3301,60))wp_die('انبار در حال ویرایش است.');try{$old=self::catalog();$clean['__commits']=is_array($old['__commits']??null)?$old['__commits']:[];$clean['__receipts']=is_array($old['__receipts']??null)?$old['__receipts']:[];update_option(self::STOCK,$clean,false);}finally{$guard->release(-3301);}wp_safe_redirect(admin_url('admin.php?page=hm-mahex-v33-station'));exit;
 }
 /** One all-or-nothing stock option write includes its idempotency marker. */
 public static function consumption(array $stock,array $usage): array {foreach($usage as $id=>$qty){if(!isset($stock[$id])||!is_numeric($qty)||!is_finite((float)$qty)||$qty<=0||$stock[$id]['stock']<$qty)throw new \InvalidArgumentException('موجودی کافی برای ماده '.$id.' وجود ندارد.');$stock[$id]['stock']-=$qty;}return $stock;}
 private static function commit($order,array &$d,array $plan): void {
  foreach(Packing::units($order) as $id=>$unit)if(!isset($d['scans'][$id]))throw new \InvalidArgumentException('تمام واحدهای سفارش باید اسکن شوند.');
  if(($d['committed_fingerprint']??'')===Packing::fingerprint(Packing::units($order)))return;
  $usage=[];foreach($plan['boxes'] as $index=>$box){$parcel=$d['parcels'][$index]??null;if(!$parcel||empty($parcel['weight_g']))throw new \InvalidArgumentException('وزن و ابعاد تمام بسته‌ها را ذخیره کنید.');$carton='carton_'.$box['profile_id'];$usage[$carton]=($usage[$carton]??0)+1;foreach($parcel['materials']??[] as $id=>$qty)$usage[$id]=($usage[$id]??0)+$qty;}
  $lock=new \HoseinMomeni\MahexWoo\Shipments\OptionOperationLock();if(!$lock->acquire(-3301,60))throw new \RuntimeException('انبار در حال ثبت است.');
  try{$stock=self::catalog();$ledger=get_option(self::LEDGER,[]);$ledger=is_array($ledger)?$ledger:[];$key=(string)$order->get_id();if(isset($ledger[$key])){$d['committed_fingerprint']=$ledger[$key]['fingerprint'];$d['committed_plan_hash']=$ledger[$key]['plan_hash']??'';return;}
   if(isset($stock['__commits'][$key])){$d['committed_fingerprint']=$stock['__commits'][$key]['fingerprint'];$d['committed_plan_hash']=$stock['__commits'][$key]['plan_hash']??'';return;}
   $next=self::consumption($stock,$usage);$fingerprint=Packing::fingerprint(Packing::units($order));
   // Journal marker kept in same stock option, making repeat calls safe if order save fails.
   if(isset($stock['__commits'][$key])){$d['committed_fingerprint']=$stock['__commits'][$key]['fingerprint'];$d['committed_plan_hash']=$stock['__commits'][$key]['plan_hash']??'';return;}
   $next['__commits']=is_array($stock['__commits']??null)?$stock['__commits']:[];$entry=['order_id'=>$order->get_id(),'usage'=>$usage,'fingerprint'=>$fingerprint,'plan_hash'=>hash('sha256',wp_json_encode($plan['boxes'])),'at'=>gmdate('c'),'actor'=>get_current_user_id()];$next['__commits'][$key]=$entry;if(!update_option(self::STOCK,$next,false))throw new \RuntimeException('ثبت موجودی در پایگاه داده انجام نشد.');$ledger[$key]=$entry;update_option(self::LEDGER,$ledger,false);$d['committed_fingerprint']=$fingerprint;$d['committed_at']=gmdate('c');$d['committed_plan_hash']=hash('sha256',wp_json_encode($plan['boxes']));
  }finally{$lock->release(-3301);}
 }
