   elseif($action==='reset'){if(!empty($d['committed_fingerprint']))throw new \RuntimeException('پس از مصرف موجودی بازنشانی خودکار مجاز نیست.');$d['scans']=[];$d['parcels']=[];$d['fingerprint']=$fp;}
