    $photos=self::mediaIds((array)($payload['photos']??[]));$cost=(float)($catalog['carton_'.$box['profile_id']]['unit_cost_irr']??$box['cost_irr']);foreach($materials as $mat=>$qty)$cost+=$qty*$catalog[$mat]['unit_cost_irr'];$d['parcels'][$index]=array_merge($d['parcels'][$index]??[],['weight_g'=>$weight,'dimensions_mm'=>$dims,'materials'=>$materials,'materials_irr'=>$cost,'photos'=>$photos,'variance_pct'=>self::variance($weight,(float)$box['actual_weight_g']),'at'=>gmdate('c')]);
