   echo '<div data-station-result></div><section data-station data-order="'.$id.'"><p data-station-status role="status" aria-live="polite">برای ویرایش، قفل ایستگاه را بگیرید.</p><button type="button" class="button" data-station-lock>شروع کار / گرفتن قفل</button> <button type="button" class="button" data-station-release>پایان کار / آزادکردن</button><p>اسکن هر واحد: SKU یا شناسه GTIN/بارکد ثبت‌شده محصول. کالا بدون این شناسه ابتدا باید در محصول تکمیل شود.</p><label>اسکن <input data-station-code autocomplete="off"></label><button class="button" type="button" data-station-scan>ثبت اسکن</button><button type="button" class="button" data-station-reset>بازنشانی اسکن و اندازه‌گیری</button><p data-station-count>'.count($d['scans']).' / '.count($units).' واحد تأییدشده</p><ul>';foreach($units as $unit)echo '<li>'.esc_html($unit['name'].' — '.implode(' / ',$unit['codes'])).'</li>';echo '</ul><p><a href="'.esc_url(add_query_arg(['page'=>'hm-mahex-manual-packing','order_id'=>$id],admin_url('admin.php'))).'">چیدمان دستی / ساخت بسته‌ها</a></p>';
   if($plan)foreach($plan['boxes'] as $i=>$box){$parcel=$d['parcels'][$i]??[];echo '<fieldset data-station-parcel="'.$i.'"><legend>بسته '.($i+1).' — '.esc_html($box['profile_name']).'</legend><label>وزن واقعی گرم <input type="number" min="1" max="1000000" data-weight value="'.esc_attr($parcel['weight_g']??'').'"></label> <button type="button" class="button" data-scale>اتصال صریح به ترازو (Web Serial)</button><p>ترازو باید متن عددی گرم با پایان خط ارسال کند؛ مرورگر پشتیبانی‌شده و HTTPS لازم است.</p><label>ابعاد میلی‌متر ';foreach($parcel['dimensions_mm']??$box['dimensions_mm'] as $size)echo '<input type="number" min="1" max="10000" data-dimension value="'.esc_attr($size).'"> ';echo '</label><p>وزن تخمینی: '.(int)$box['actual_weight_g'].' گرم؛ هشدار اختلاف بیشتر از ۱۰٪</p><label>مواد مصرفی (JSON شناسه: تعداد) <textarea data-materials>'.esc_textarea(wp_json_encode($parcel['materials']??[],JSON_UNESCAPED_UNICODE)).'</textarea></label><input type="hidden" data-photos value="'.esc_attr(wp_json_encode($parcel['photos']??[])).'"><button type="button" class="button" data-photos-button>انتخاب عکس بسته</button><button type="button" class="button button-primary" data-measure>ذخیره اندازه‌گیری</button><p data-parcel-result>'.esc_html(isset($parcel['materials_irr'])?'هزینه مواد: '.$parcel['materials_irr'].' ریال؛ اختلاف وزن: '.round($parcel['variance_pct']??0,1).'%':'').'</p><label>کد رهگیری این بسته <input data-tracking value="'.esc_attr($parcel['tracking']??'').'"></label><input type="hidden" data-pdf value="'.esc_attr(wp_json_encode($parcel['official_pdf']??[])).'"><button type="button" class="button" data-pdf-button>انتخاب PDF رسمی دریافت‌شده</button><button type="button" class="button" data-tracking-save>ثبت رهگیری مستقل</button></fieldset>';}
   echo '<button type="button" class="button button-primary" data-station-commit>تأیید مصرف موجودی ایستگاه (یک بار)</button><h2>جمع‌آوری و تحویل</h2><label>از <input type="datetime-local" data-pickup-start></label><label>تا <input type="datetime-local" data-pickup-end></label><input data-pickup-note placeholder="یادداشت"><button type="button" class="button" data-pickup-save>ثبت رزرو داخلی جمع‌آوری</button><p>رزرو داخلی است و به شرکت حمل ارسال نمی‌شود.</p><label>نام دریافت‌کننده <input data-receiver></label><canvas width="600" height="180" data-signature aria-label="امضای دریافت‌کننده"></canvas><button type="button" class="button" data-signature-clear>پاک‌کردن امضا</button><button type="button" class="button" data-handover>ثبت دفتر تحویل و امضا</button>';
   if(!empty($d['handover']))echo '<p>تحویل ثبت‌شده: '.esc_html($d['handover']['receiver'].' — '.$d['handover']['at']).'</p><img class="hmx-signature-preview" alt="امضای دریافت‌کننده" src="'.esc_attr($d['handover']['signature']).'">';
   echo '<h2>پیشنهاد هندسی کم‌هزینه</h2><p>چیدمان محورموازی، حداکثر ۲۰۰ واحد؛ تضمین بهینگی یا استحکام نیست. هزینه تخمینی بر اساس کرایه پایه/کیلو و مواد است؛ نرخ استان و قواعد ویژه را اعمال نمی‌کند. گروه‌های ناسازگار باید جدا شوند. ابعاد کالا از محصول یا مقادیر جایگزین تنظیمات می‌آیند؛ داده ناقص محصول را پیش از اتکا به پیشنهاد تکمیل کنید.</p>';foreach(array_slice($recommend,0,5) as $i=>$candidate)echo '<button type="button" class="button" data-preview="'.$i.'">'.esc_html($candidate['name'].' — '.$candidate['total_irr'].' ریال').'</button>';echo '<canvas width="720" height="420" data-packing-3d aria-label="نمای ایزومتریک چیدمان سه‌بعدی"></canvas>';
   echo '<script type="application/json" data-station-data>'.wp_json_encode(['state'=>$d,'recommend'=>$recommend,'units'=>$units],JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP).'</script></section>';
  }
  self::stockPage();echo '</div>';
 }
 public static function demand(): array {$demand=[];foreach(wc_get_orders(['limit'=>200,'status'=>['pending','on-hold','processing'],'orderby'=>'date','order'=>'DESC']) as $order){if(!Access::can('packing',$order->get_id())||!empty(self::data($order)['committed_fingerprint']))continue;$plan=Packing::snapshot($order);foreach($plan['boxes']??[] as $box){$id='carton_'.$box['profile_id'];$demand[$id]=($demand[$id]??0)+1;}}return $demand;}
 public static function purchase(): void {
  if(!Access::can('settings'))wp_die('دسترسی انبار مجاز نیست.','',['response'=>403]);check_admin_referer('hm_mahex_v33_purchase');$intent=isset($_POST['intent'])&&is_string($_POST['intent'])?sanitize_key($_POST['intent']):'';$lock=new \HoseinMomeni\MahexWoo\Shipments\OptionOperationLock();if(!$lock->acquire(-3301,60))wp_die('انبار در حال ویرایش است.');$error=null;
  try{$stock=self::catalog();$orders=get_option('hm_mahex_v33_purchase_orders',[]);$orders=is_array($orders)?$orders:[];
   if($intent==='create'){$demand=self::demand();$lines=[];foreach($stock as $id=>$row){if(strpos((string)$id,'__')===0)continue;$qty=max(0,(float)$row['target_stock']+($demand[$id]??0)-(float)$row['stock']);if($qty>0)$lines[$id]=['qty'=>$qty,'unit_cost_irr'=>(float)$row['unit_cost_irr'],'name'=>$row['name']];}if(!$lines)throw new \RuntimeException('کمبودی برای سفارش خرید وجود ندارد.');$key=wp_generate_uuid4();$orders[$key]=['id'=>$key,'lines'=>$lines,'created_at'=>gmdate('c'),'actor'=>get_current_user_id(),'status'=>'draft','supplier'=>sanitize_text_field((string)($_POST['supplier']??''))];if(!update_option('hm_mahex_v33_purchase_orders',$orders,false))throw new \RuntimeException('سفارش خرید ذخیره نشد.');}
   elseif($intent==='receive'){$key=isset($_POST['purchase_id'])&&is_string($_POST['purchase_id'])?sanitize_text_field(wp_unslash($_POST['purchase_id'])):'';$po=$orders[$key]??null;if(!$po)throw new \RuntimeException('سفارش خرید پیدا نشد.');if(!isset($stock['__receipts'][$key])){foreach($po['lines'] as $id=>$line){if(!isset($stock[$id]))throw new \RuntimeException('ماده '.$id.' در موجودی وجود ندارد.');$stock[$id]['stock']+=(float)$line['qty'];}$stock['__receipts'][$key]=['at'=>gmdate('c'),'actor'=>get_current_user_id()];if(!update_option(self::STOCK,$stock,false))throw new \RuntimeException('رسید موجودی ذخیره نشد.');}$orders[$key]['status']='received';$orders[$key]['received_at']=$stock['__receipts'][$key]['at'];update_option('hm_mahex_v33_purchase_orders',$orders,false);}
   else throw new \InvalidArgumentException('عملیات خرید نامعتبر است.');
  }catch(\Throwable $e){$error=$e->getMessage();}finally{$lock->release(-3301);}if($error)wp_die(esc_html($error));wp_safe_redirect(admin_url('admin.php?page=hm-mahex-v33-station'));exit;
 }
 private static function stockPage(): void {
  if(!Access::can('settings'))return;
  $catalog=self::catalog();$demand=self::demand();$markers=$catalog['__commits']??[];unset($catalog['__commits'],$catalog['__receipts']);echo '<h2>موجودی تأییدشده ایستگاه و پیشنهاد خرید</h2><p>این موجودی مستقل از کسر خودکار قدیمی است؛ موجودی اولیه واقعی را یک بار وارد کنید. شناسه کارتن باید carton_ و شناسه پروفایل باشد. مواد مانند tape و bubble قابل تعریف‌اند؛ هزینه‌ها ریال است.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="hm_mahex_v33_stock">';wp_nonce_field('hm_mahex_v33_stock');$example=$catalog;if(!$example){foreach(PackagingProfiles::all() as $profileId=>$profile)$example['carton_'.$profileId]=['name'=>(string)($profile['name']??$profileId),'stock'=>0,'unit_cost_irr'=>(float)($profile['unit_cost_irr']??0),'min_stock'=>5,'target_stock'=>20];$example['tape']=['name'=>'چسب','stock'=>0,'unit_cost_irr'=>0,'min_stock'=>5,'target_stock'=>20];}echo '<textarea name="catalog" rows="8" class="large-text code" dir="ltr">'.esc_textarea(wp_json_encode($example,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)).'</textarea><button class="button">ثبت موجودی و هزینه مواد</button></form><table class="widefat"><tr><th>ماده</th><th>موجودی</th><th>پیشنهاد خرید تا هدف</th><th>برآورد هزینه خرید</th></tr>';foreach($catalog as $id=>$row){$buy=max(0,$row['target_stock']+($demand[$id]??0)-$row['stock']);echo '<tr><td>'.esc_html($row['name']).'</td><td>'.esc_html($row['stock']).'</td><td>'.esc_html($buy).'</td><td>'.esc_html($buy*$row['unit_cost_irr']).' ریال</td></tr>';}echo '</table><p>پیشنهاد خرید شامل تقاضای کارتن از طرح‌های بسته‌بندی آخرین ۲۰۰ سفارش باز است؛ سفارش خرید داخلی بوده و به تأمین‌کننده ارسال نمی‌شود.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="hm_mahex_v33_purchase"><input type="hidden" name="intent" value="create">';wp_nonce_field('hm_mahex_v33_purchase');echo '<input name="supplier" placeholder="نام تأمین‌کننده"><button class="button">ساخت سفارش خرید از کمبود و تقاضا</button></form>';foreach(array_slice(array_reverse((array)get_option('hm_mahex_v33_purchase_orders',[]),true),0,20,true) as $purchase){echo '<details><summary>'.esc_html($purchase['id'].' — '.$purchase['status']).'</summary><p>'.esc_html(wp_json_encode($purchase['lines'],JSON_UNESCAPED_UNICODE)).'</p>';if($purchase['status']!=='received'){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="hm_mahex_v33_purchase"><input type="hidden" name="intent" value="receive"><input type="hidden" name="purchase_id" value="'.esc_attr($purchase['id']).'">';wp_nonce_field('hm_mahex_v33_purchase');echo '<button class="button">تأیید دریافت کامل و افزودن موجودی (یک بار)</button></form>';}echo '</details>';}echo '<details><summary>دفتر مصرف تأییدشده</summary><ul>';foreach(array_slice(array_reverse($markers,true),0,30,true) as $entry)echo '<li>سفارش #'.(int)$entry['order_id'].' — '.esc_html($entry['at'].' — '.wp_json_encode($entry['usage'],JSON_UNESCAPED_UNICODE)).'</li>';echo '</ul></details>';
 }
}
